  import { bracketBareIPv6Host } from "@lib/ws";
  export function setServerHost(host: string): void {
    const stripped = /:443$/.test(host) && (!host.slice(0, -4).includes(":") || host.slice(0, -4).endsWith("]"))
      ? host.slice(0, -4)
      : host;
    _serverHost = bracketBareIPv6Host(stripped).toLowerCase();
  }

